svg.script:
// *************************************************************************
// /=rl radial, -=orbital, *=pl animate, vc=? !=tm +=zoom
var main = { 
  "rl":0, "pl":0, "ro":0, "vc":0, "ex":0, "vi":0, "tm":0,
  "MIN": 60000, "IV":1000, "AC":27, "AP":8, "DUR":"10000",
  "VS":[1,3.5,18,27,81], "PT":'M 0,0 L 1,1'
};
main.getf=function(f) { var r=false; if (f) { var e=f.firstChild; if (e) { 
  r=e.nodeValue;
}} return r; };
main.setf=function(f,v) { if (f) { var e=f.firstChild; if (e) { 
      var u=(v ? ""+v : ""); e.nodeValue=u.trim(); 
    }}};

main.geta = function(o,n) { return (!o || !n ? false : o.getAttribute(n)); };
main.seta = function(o,n,v) { if (o) { if (n) { o.setAttribute(n,""+v); }}};
main.goa = function(m,f) {
  var b,i,z; z=m.ma; if (z) { for (i=0;i<m.AP;i++) { b=z[i]; if (b) { 
	if (f) { b.beginElement(); } else { b.endElement(); }
      }}}
};
main.show=function(m) { 
  var e,j,s,t,z; e=m.ira; t=m.paa; z=m.sa; if (e && t && z) {    
    s=(m.rl ? "/" : "")+(m.ro ? "-" : "")+
      (m.pl ? "*"+(m.pl>1 ? m.pl : "") : "")+
      (m.vc ? "="+(m.vc>1 ? m.vc : "") : "")+
      (m.vi ? "+"+(m.vi>1 ? m.vi : "") : "")+
      "["+t.join(' ')+"]["+e.join(' ')+(m.irn==e[4] ? "" : ":"+m.irn)+"]";
    t=z[0]; if (t) { m.setf(t,s); }
    t=z[1]; if (t) { m.setf(t,s); }
  }
  j=m.vc; e=m.gt; if (e) { 
    t=(m.rl ? 'grl ' : '')+(m.ro ? 'gro ' : '')+(m.pl ? 'gpl ' : '');
    m.seta(e,'class','gt'+j+' '+t); 
  }
  e=m.g; if (e) { m.seta(e,'class','gt'+j); }
  e=m.ge; z=m.VS; t=m.vi; if (e && t<z.length) {
    k=z[t]; if (k) { m.seta(e,'transform','scale('+k+')'); }
  }
};
main.plot=function(m) {
  var a,b,c,i,j,k,n,s,t,u,w,v,y,z,ct,pb,pe,ib,ie,yd,ym; 
  yd=365.25; ym=yd/12; a=m.psa; b=m.pia; v=m.paa; y=m.ira; 
  m.goa(m,false);
  if (a && b && v && y) {
    pb=(v[0]*yd)+(v[1]*ym); pe=(v[2]*yd)+(v[3]*yd); k=v[4]; // days
    ib=(y[0]*yd)+(y[1]*ym); ie=(y[2]*yd)+(y[3]*yd); n=m.irn;  // skip
    if (pb<pe && ib<ie && k>0 && n>0) {
      k=k*n; u=[]; for (i=0;i<m.AP;i++) { u[i]=b[i]; } // make copy to change
      ct=0; b=u; w=0; v=[]; y=[]; for (c=pb;c<pe && c<ie;c=c+k) { // scan all
	if (c>ib) { // if in range
	  u=[]; for (i=0;i<m.AP;i++) { t=a[i]; if (t) {
	      z=b[i]; j=t.indexOf(' ',z); if (j>-1) { 
		u[i]=t.substr(z,j-z); b[i]=j+1; if (m.ro || m.pl) {
		  s=y[i]; y[i]=(!s ? 'M ' : s)+u[i]+(!s ? ' L ' : ' ');
		}
	      }
	    }}
	  // next points in u, add to paths
	  if (!(ct%n)) { 
	    if (m.rl && u.length) { 
	      s=v[w]; v[w]=(s ? s+' ': "")+'M '+u[0]+' L '+u.join(' ');
	      w=(w+1)%(m.AC);
	    }
	  }
	  ct++;
	}
      }
      if (m.rl) { z=m.ca; if (z && v.length) { 
	  for (i=0;i<m.AC;i++) { t=z[i]; u=v[i]; if (t && u) { 
	      m.seta(t,'d',u); 
	    }}
	}}
      j=m.pl; if (j || m.ro) { 
	z=m.ga; if (z && y.length) { 
	  for (i=0;i<m.AP;i++) { t=z[i]; u=y[i]; if (t && u) { 
	      m.seta(t,'d',u); 
	    }}
	}
	if (j) { w=m.DUR; z=m.ma; if (w && z) { 
	    for (i=0;i<m.AP;i++) { t=z[i]; if (t) { 
		m.seta(t,"dur",w.substr(0,6-j)); 
	      }}
	    m.goa(m,true); 
	  }
	}
      }
    }
  }
};

main.clear = function(m) {
  var i,e,y,z; y=m.PT; m.goa(m,false);
  z=m.ca; if (z) { for (i=0;i<m.AC;i++) { e=z[i]; if (e) { m.seta(e,'d',y); }}}
  z=m.ga; if (z) { for (i=0;i<m.AP;i++) { e=z[i]; if (e) { m.seta(e,'d',y); }}}
};
main.reset = function(m) { 
  var y=m.ira; if (y) { m.irn=y[4]; }
  m.rl=0; m.pl=0; m.ro=0; m.vc=0; m.ex=0; m.vi=0; 
};
main.hash = function() {
  var i,j,k,e,m,p,t,u,v,y,z; m=main; i=m.loc; if (i) {
    m.hsh=null; p=i.hash; u=false; if (p && p.length>1) { 
      p=p.substr(1); m.hsh=p; u=p.split(','); 
    }
    e=false; k=1; t=(u ? u.length : 0); switch(t) {
    case 1: p=parseInt(u[0],10); if (!isNaN(p)) { k=p; } // just the increment
    case 0: 
      j=new Date(); v=j.getMonth()+1; y=j.getFullYear(); e=[v,y,v,y+100,k];
      break;
    case 2: 
      p=parseInt(u[0],10); k=parseInt(u[1],10); if (!isNaN(p+k)) {
	j=new Date(); v=j.getMonth()+1; y=j.getFullYear(); 
	e=(k<y ? [p,k,v,y,1] : [v,y,p,k,1]);
      }
      break;
    case 4:
    case 5:
      p=parseInt(u[0],10); k=parseInt(u[1],10); p=(p%12);
      v=parseInt(u[2],10); y=parseInt(u[3],10); v=(v%12);
      j=(t==5 ? parseInt(u[4],10) : 1); 
      if (!isNaN(p+k+v+y+j)) { e=(k<y ? [p,k,v,y,j] : [v,y,p,k,j]); }
      break;
    default: break;
    }
    m.ira=e; m.irn=e[4]; m.clear(m); m.show(m); if (m.tm) { m.plot(m); }
  }
};

main.ccb = function(m,n) { 
  var e,f,j,k,t; e=m.irn; k=m.VS; j=k.length; if (e && j) { 
    f=false; switch(n) {
    case 0: m.vi=(m.vi+(j-1))%j; f=true; break;
    case 5: m.vi=(m.vi+1)%j; f=true; break;
    case 10: m.rl=(1-m.rl); f=true; break; // radial
    case 11: m.ro=(1-m.ro); f=true; break; // circular
    case 12: m.pl=(m.pl+1)%4; f=true; break; // planets
    case 13: m.vc=(m.vc+1)%6; f=true; break; // rings
    case 14: m.irn=(m.irn+1); f=true; break; // skip
    case 20: m.reset(m); m.clear(m); f=true; break; // undo it
    case 21: // do it
      if (m.rl || m.pl || m.ro) { m.clear(m); m.plot(m); f=true; }    
      break; 
    default: break;
    }
    if (f) { m.show(m); }
  }
};
main.qry = function(m) {
  var e,i,j,p,t,u,y,z,dn; u=m.VS; e=u.length; y=m.loc; if (y) { 
    p=y.search; if (p) { p=p.substr(1); j=p.length; if (j) {
	m.qst=p; dn=false; for (i=0;i<j && !dn;i++) { t=p.charAt(i); switch(t) {
          case '/': m.rl=1; break;
          case '-': m.ro=1; break;
          case '*': m.pl=(m.pl+1)%4; break;
          case '=': m.vc=(m.vc+1)%6; break;
          case '+': m.vi=(m.vi+1)%e; break;
          case '!': m.tm=1; break;
          default: 
            if (t) { u=parseInt(p.substr(j),10); if (!isNaN(u)) { 
		dn=true; m.ex=u; // timer...
	      }}
	    break;
	  }}	
      }}
  }
};
main.init = function(m,g,w) { if (g && w && !m.win) {
    var a,b,d,i,j,x,y; m.win=w; m.g=g; m.b=g.parentNode; d=m.b.parentNode; 
    m.loc=w.location; m.HOUR=Math.round(60*m.MIN); m.DAY=Math.round(24*m.HOUR);
    m.YEAR=Math.round(365.25*m.DAY); m.CERES=-180;
    x=Math.round((29*m.DAY)+(12*m.HOUR)+(44*m.MIN))+2900; 
    m.MON=x; m.MONS=Math.round(x/1000); m.YMON=m.YEAR/12; 
    m.WINTER=Date.parse('21 December 2020');m.RAT=Date.parse('25 January 2020');
    d=document; if (d) { 
      m.doc=d; a=[];
      for (i=0;i<m.AC;i++) { x=d.getElementById('ac'+i); if (x) { a[i]=x; }}
      m.ca=a; a=[];
      for (i=0;i<m.AP;i++) { x=d.getElementById('ag'+i); if (x) { a[i]=x; }}
      m.ga=a; a=[];
      for (i=0;i<m.AP;i++) { x=d.getElementById('am'+i); if (x) { a[i]=x; }}
      m.ma=a; a=[];
      for (i=0;i<3;i++) { x=d.getElementById('as'+i); if (x) { a[i]=x; }}
      m.sa=a; a=[];
      x=d.getElementById('los'); if (x) { m.gt=x; }
      x=d.getElementById('lobos'); if (x) { m.ge=x; }
      x=d.getElementById('ann'); if (x) { y=m.getf(x); if (y) {
	  a=y.split(','); if (a && a.length==5) { 
	    b=[]; for (i=0;i<5;i++) { b[i]=parseInt(a[i],10); }
	    m.paa=b; a=[]; b=[]; 
	    for (i=0;i<m.AP;i++) { x=d.getElementById('an'+i); if (x) { 
		y=m.geta(x,'d'); if (y) { j=y.indexOf(' L '); if (j>0) { 
		    a[i]=y; b[i]=j+3;
		  }}
	      }}
	    m.psa=a; m.pia=b;
	  }
	}}
      m.qry(m); m.hash(); w.onhashchange=main.hash;
    }
  }};
main.initg = function(e) { if (e) { var t=e.target; if (t) {
      main.init(main,t,window);
    }}};
main.inits = function(e) { if (e) { var t=e.target; if (t) {
      main.init(main,t.lastElementChild,window);
    }}};
